<template>
  <view :class="['ppt-v2', `ppt-v2--${mode}`]" :style="miniProgramNavigationStyle">
    <view class="ppt-nav">
      <button v-if="mode !== 'index'" class="icon-button" aria-label="返回" @click="goBack">‹</button>
      <view v-else class="nav-spacer" />
      <text class="ppt-nav-title">{{ pageTitle }}</text>
      <view class="nav-spacer" />
    </view>

    <AiGeneratedContentNotice />

    <view v-if="mode === 'index'" class="ppt-content home-content">
      <view class="ppt-hero"><text class="hero-icon">▣</text><view><text>AI帮你快速生成专业PPT</text><text>输入主题，智能生成大纲和内容</text></view></view>
      <view class="quick-create"><textarea v-model="quickTopic" maxlength="120" placeholder="输入PPT主题或内容要点" /><button :disabled="!quickTopic.trim()" @click="openCreate({ topic: quickTopic })">开始创建</button></view>
      <view class="section-heading"><text>模板推荐</text><button @click="showToast('更多模板将在后续版本开放')">更多 ›</button></view>
      <view class="template-row"><button v-for="item in templates.slice(0,3)" :key="item.id" :class="item.tone" @click="openCreate({ templateId: item.id, scenario: item.scenario })"><text>{{ item.icon }}</text><text>{{ item.name }}</text></button></view>
      <view class="section-heading"><text>最近PPT</text><button @click="openAssets">查看更多 ›</button></view>
      <view v-if="historyLoading" class="state-card"><text>正在加载最近演示文稿...</text></view>
      <view v-else-if="historyError" class="state-card error"><text>{{ historyError }}</text><button @click="loadHistory">重新加载</button></view>
      <view v-else-if="recent.length" class="recent-list"><button v-for="item in recent" :key="item.taskId" @click="openDetail(item.taskId)"><text class="recent-icon">▤</text><view><text>{{ item.title }}</text><text>{{ formatDate(item.updatedAt || item.createdAt) }} · {{ item.slideCount || item.slides?.length || 0 }}页</text></view><text>›</text></button></view>
      <view v-else class="state-card"><text>还没有PPT作品</text><text>输入主题，创建第一份演示文稿。</text></view>
    </view>

    <scroll-view v-else-if="mode === 'create'" class="ppt-scroll" scroll-y>
      <view class="ppt-content create-content">
        <label class="field"><text>PPT主题</text><input v-model="form.topic" maxlength="120" placeholder="请输入演示文稿主题" /></label>
        <label class="field"><text>补充说明（选填）</text><textarea v-model="form.description" maxlength="600" placeholder="受众、目标、需要强调的数据或结论" /></label>
        <text class="section-title">生成设置</text>
        <view class="setting-list">
          <picker class="setting-item" :range="pageCounts" :value="pageCountIndex" @change="setPageCount"><view class="setting-row"><text>页数</text><text>{{ form.pageCount }}页 ›</text></view></picker>
          <picker class="setting-item" :range="languages.map(item => item.label)" :value="languageIndex" @change="setLanguage"><view class="setting-row"><text>语言</text><text>{{ languageLabel }} ›</text></view></picker>
          <picker class="setting-item" :range="scenarios.map(item => item.label)" :value="scenarioIndex" @change="setScenario"><view class="setting-row"><text>演示场景</text><text>{{ scenarioLabel }} ›</text></view></picker>
          <picker class="setting-item" :range="styles.map(item => item.label)" :value="styleIndex" @change="setStyle"><view class="setting-row"><text>设计风格</text><text>{{ styleLabel }} ›</text></view></picker>
          <picker class="setting-item" :range="templates.map(item => item.name)" :value="templateIndex" @change="setTemplate"><view class="setting-row"><text>选择模板</text><text>{{ templateLabel }} ›</text></view></picker>
        </view>
        <text class="section-title">参考资料</text>
        <view class="reference-row"><button disabled>＋ 上传文件（即将开放）</button><button disabled>▦ 从知识库选择（即将开放）</button></view>
        <view v-if="form.referenceFileIds.length" class="file-chip"><text>已添加 {{ form.referenceFileIds.length }} 个参考文件</text><button @click="form.referenceFileIds = []">清除</button></view>
        <view class="switch-row"><view><text>生成演讲稿</text><text>为每页补充演讲备注</text></view><switch :checked="form.generateSpeakerNotes" color="#6140f7" @change="toggleSpeakerNotes" /></view>
        <view class="switch-row"><view><text>生成配图</text><text>根据页面内容生成视觉素材</text></view><switch :checked="form.generateVisuals" color="#6140f7" @change="toggleVisuals" /></view>
        <view v-if="createError || estimate?.sufficient === false" class="inline-error"><text>{{ createError || `可用点数不足，本次预计需要 ${estimate?.pointCost || 0} 点` }}</text><button v-if="createError.includes('余额') || estimate?.sufficient === false" @click="openWallet">前往钱包</button></view>
      </view>
      <view class="bottom-space" />
    </scroll-view>

    <scroll-view v-else-if="mode === 'outline'" class="ppt-scroll" scroll-y>
      <view class="ppt-content">
        <text class="eyebrow">PPT主题</text><text class="outline-topic">{{ outline.title }}</text>
        <view class="outline-meta"><text>共{{ outline.slides.length }}页</text><button :disabled="busy" @click="regenerateOutline">重新生成大纲</button></view>
        <view class="outline-list"><view v-for="(item,index) in outline.slides" :key="`${item.page}-${index}`" class="outline-card"><text class="number">{{ index+1 }}</text><view><input v-model="item.title" maxlength="60" /><textarea v-model="item.summary" maxlength="180" /></view><view class="outline-actions"><button :disabled="index===0" aria-label="上移" @click="moveOutline(index,-1)">↑</button><button :disabled="index===outline.slides.length-1" aria-label="下移" @click="moveOutline(index,1)">↓</button><button aria-label="删除" @click="removeOutline(index)">×</button></view></view></view>
        <button class="add-outline" @click="addOutline">＋ 添加章节</button>
        <view class="generation-summary"><text>{{ outline.slides.length }}页 · {{ estimate?.pointCost ?? '待试算' }}点</text><text>{{ templateLabel }} · {{ form.generateVisuals ? '生成配图' : '无配图' }}</text></view>
        <text v-if="createError" class="inline-error">{{ createError }}</text>
      </view><view class="bottom-space" />
    </scroll-view>

    <view v-else-if="mode === 'progress'" class="ppt-content progress-content">
      <view class="progress-ring" :style="{ '--progress': `${taskProgress * 3.6}deg` }"><view><text>{{ taskProgress }}%</text><text>正在生成第{{ pollingTask?.currentPage || Math.max(1, Math.ceil(taskProgress / Math.max(1, 100 / totalSlides))) }}页</text></view></view>
      <text class="progress-hint">任务会在后台继续，离开页面不会中断</text>
      <view class="steps"><view v-for="step in progressSteps" :key="step.id" :class="step.state"><text>{{ step.state === 'done' ? '✓' : step.state === 'active' ? '●' : '○' }}</text><text>{{ step.label }}</text><text>{{ step.state === 'done' ? '已完成' : step.state === 'active' ? '进行中' : '等待中' }}</text></view></view>
      <view v-if="pollingError" class="inline-error"><text>{{ pollingError }}</text><button @click="taskState.refresh">重试连接</button></view>
      <view class="bottom-actions"><button @click="cancelTask">取消生成</button><button class="primary" @click="continueInBackground">后台继续</button></view>
    </view>

    <scroll-view v-else-if="mode === 'detail'" class="ppt-scroll" scroll-y>
      <view class="ppt-content">
        <view v-if="detailLoading" class="state-card"><text>正在加载PPT...</text></view>
        <PptErrorView v-else-if="detailError" title="PPT加载失败" :reason="detailError" @retry="loadDetail" @back="goBack" />
        <template v-else>
          <view class="detail-title"><view><text>{{ detail.title }}</text><text>创建于 {{ formatDate(detail.createdAt) }} · 共{{ detail.slides?.length || detail.slideCount || 0 }}页</text></view><text :class="['status-pill', detail.status]">{{ statusLabel(detail.status) }}</text></view>
          <view class="detail-tools"><button @click="openPreview(0)"><text>▣</text><text>预览</text></button><button @click="openTextEditor(0)"><text>✎</text><text>编辑文字</text></button><button @click="openVisualEditor(0)"><text>◉</text><text>编辑视觉</text></button><button @click="openExport"><text>⇧</text><text>导出</text></button><button @click="showDetailMore"><text>•••</text><text>更多</text></button></view>
          <view class="slide-grid"><button v-for="(slide,index) in detail.slides || []" :key="slide.id" @click="openPreview(index)"><view class="slide-preview"><image v-if="slide.imageUrl" :src="slide.imageUrl" mode="aspectFill" lazy-load /><view v-else><text>{{ slide.title }}</text><text v-for="point in slide.bulletPoints?.slice(0,2)" :key="point">{{ point }}</text></view></view><text>{{ index+1 }}</text><text v-if="slide.visualStatus === 'failed'" class="slide-failed">配图失败</text></button></view>
        </template>
      </view><view class="bottom-space" />
    </scroll-view>

    <view v-else-if="mode === 'preview'" class="preview-page">
      <text class="preview-count">{{ previewIndex+1 }} / {{ slides.length }}</text>
      <swiper class="preview-swiper" :current="previewIndex" @change="previewIndex = Number($event.detail.current)"><swiper-item v-for="slide in slides" :key="slide.id"><view class="full-slide"><image v-if="slide.imageUrl" :src="slide.imageUrl" mode="aspectFit" /><view v-else><text>{{ slide.title }}</text><text v-for="point in slide.bulletPoints" :key="point">• {{ point }}</text></view></view></swiper-item></swiper>
      <view class="preview-actions"><button @click="previewIndex=Math.max(0,previewIndex-1)">‹<text>上一页</text></button><button open-type="share">⇧<text>分享</text></button><button @click="openTextEditor(previewIndex)">✎<text>编辑</text></button><button @click="previewIndex=Math.min(slides.length-1,previewIndex+1)">›<text>下一页</text></button></view>
    </view>

    <scroll-view v-else-if="mode === 'edit-text'" class="ppt-scroll" scroll-y><view class="ppt-content edit-form"><label class="field"><text>页面标题</text><input v-model="activeSlide.title" /></label><label class="field"><text>副标题</text><input v-model="activeSlide.content" /></label><label class="field"><text>正文内容</text><textarea v-model="bulletText" class="large-textarea" /></label><label class="field"><text>页脚 / 演讲稿</text><textarea v-model="activeSlide.speakerNotes" /></label><view class="ai-actions"><button v-for="action in aiTextActions" :key="action" @click="applyTextAction(action)">{{ action }}</button></view><text v-if="createError" class="inline-error">{{ createError }}</text></view><view class="bottom-space" /></scroll-view>

    <scroll-view v-else-if="mode === 'edit-visual'" class="ppt-scroll" scroll-y><view class="ppt-content"><text class="section-title">背景（即将开放）</text><view class="color-row"><button v-for="color in themeColors" :key="color" :style="{background:color}" :class="{selected:selectedColor===color}" disabled /></view><text class="section-title">配图</text><view class="visual-editor"><view class="slide-preview"><image v-if="activeSlide.imageUrl" :src="activeSlide.imageUrl" mode="aspectFill" /><text v-else>当前页暂无配图</text></view><view><button :disabled="busy" @click="chooseVisual">更换图片</button><button class="primary" :disabled="busy" @click="regenerateVisual">{{ busy ? '生成中...' : 'AI生成图片' }}</button></view></view><text class="section-title">字体（即将开放）</text><view class="setting-list"><view><text>字体风格</text><text>思源黑体</text></view></view><text v-if="createError" class="inline-error">{{ createError }}</text></view><view class="bottom-space" /></scroll-view>

    <scroll-view v-else-if="mode === 'layout'" class="ppt-scroll" scroll-y><view class="ppt-content"><view class="layout-tabs"><button v-for="tab in layoutTabs" :key="tab" :class="{active:layoutTab===tab}" @click="layoutTab=tab">{{ tab }}</button></view><view class="layout-grid"><button v-for="item in filteredLayouts" :key="item.id" :class="{selected:selectedLayout===item.id}" @click="selectedLayout=item.id"><view class="layout-preview"><text>{{ item.icon }}</text><view><text /><text /><text /></view></view><text>{{ item.name }}</text></button></view><text v-if="createError" class="inline-error">{{ createError }}</text></view><view class="bottom-space" /></scroll-view>

    <view v-else-if="mode === 'export'" class="ppt-content export-content"><view class="export-tabs"><button v-for="format in exportFormats" :key="format" :class="{active:exportFormat===format}" @click="exportFormat=format">{{ format.toUpperCase() }}</button></view><view class="export-card"><text>▤</text><view><text>{{ exportFormat.toUpperCase() }}文件</text><text>{{ exportFormat==='pptx' ? '适合在 PowerPoint 中继续编辑' : '适合预览和分享' }}</text></view></view><view class="export-progress"><view><text>导出状态</text><text>{{ exportBusy ? '正在生成文件...' : exportReady ? '文件已准备好' : '等待导出' }}</text></view><view><view :style="{width:exportBusy?'60%':exportReady?'100%':'0%'}" /></view></view><text v-if="createError" class="inline-error">{{ createError }}</text><view class="export-actions"><button :disabled="exportBusy" @click="startExport">⇩<text>{{ exportReady ? '重新下载' : '下载到本地' }}</text></button><button @click="copyUnavailable">↗<text>复制链接</text></button><button open-type="share">◉<text>微信好友</text></button><button @click="showToast('更多分享方式由微信提供')">•••<text>更多</text></button></view></view>

    <view v-else-if="mode === 'desktop'" class="ppt-content desktop-content"><text>在电脑浏览器中继续编辑此PPT</text><view class="qr-placeholder">▦</view><view class="desktop-link"><text>安全临时链接需由后端生成</text></view><button disabled>复制链接</button><view class="security-note"><text>安全提示</text><text>该入口不会暴露长期登录 Token。一次性短期令牌接口接入后即可启用。</text></view></view>

    <PptErrorView v-else class="ppt-content" :title="errorTitle" :reason="errorReason" :suggestion="errorSuggestion" @back="goBack" @retry="retryFromError" />

    <view v-if="showFixedBar" class="fixed-bar"><text v-if="mode==='create'">预计消耗：◆ {{ estimate?.pointCost ?? '--' }}</text><button v-if="mode==='create'" class="primary" :disabled="!canSubmitCreate" @click="submitCreate">{{ busy ? '生成大纲中...' : '下一步' }}</button><button v-else-if="mode==='outline'" @click="addOutline">＋ 添加章节</button><button v-if="mode==='outline'" class="primary" :disabled="busy || !outline.slides.length" @click="confirmGeneration">{{ busy ? '提交中...' : '确认生成PPT' }}</button><button v-if="mode==='edit-text'" @click="goBack">取消</button><button v-if="mode==='edit-text'" class="primary" :disabled="busy" @click="saveText">{{ busy ? '保存中...' : '保存' }}</button><button v-if="mode==='edit-visual'" @click="goBack">取消</button><button v-if="mode==='edit-visual'" class="primary" @click="goBack">完成</button><button v-if="mode==='layout'" @click="goBack">取消</button><button v-if="mode==='layout'" class="primary" :disabled="busy" @click="applyLayout">应用布局</button></view>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { onHide, onShow, onUnload } from "@dcloudio/uni-app";
import { createPptGenerationTask, deletePptTask, downloadPptExport, estimatePptCost, generatePptOutline, getPptGenerationTask, listPptHistory, regeneratePptSlideVisual, savePptOutline, updatePptSlide, updatePptSlideImage, type PptCostEstimate, type PptHistoryItem, type PptOutline, type PptSlide, type PptTaskResponse } from "../../api/ppt";
import { uploadReferenceImage } from "../../api/files";
import { usePptDraft } from "../../composables/usePptDraft";
import { usePptTask } from "../../composables/usePptTask";
import { inspirationAPI } from "../../features/inspiration/api";
import { readInspirationDraft } from "../../features/inspiration/draft";
import AiGeneratedContentNotice from "../../components/compliance/AiGeneratedContentNotice.vue";
import PptErrorView from "./PptErrorView.vue";

type Mode = "index"|"create"|"outline"|"progress"|"detail"|"preview"|"edit-text"|"edit-visual"|"layout"|"export"|"desktop"|"error";
const props = defineProps<{ mode: Mode }>();
const mode = computed(() => props.mode);
const { form, clearDraft } = usePptDraft();
const taskState = usePptTask();
const pollingTask = taskState.task;
const pollingError = taskState.error;
type SwitchChangeEvent = Event & { detail: { value: boolean | string } };
function switchValue(event: Event) { return Boolean((event as SwitchChangeEvent).detail.value); }
function toggleSpeakerNotes(event: Event) { form.value.generateSpeakerNotes = switchValue(event); }
function toggleVisuals(event: Event) { form.value.generateVisuals = switchValue(event); }
const quickTopic = ref(""); const busy = ref(false); const createError = ref(""); const estimate = ref<PptCostEstimate|null>(null);
const recent = ref<PptHistoryItem[]>([]); const historyLoading=ref(false); const historyError=ref("");
const outline = ref<PptOutline>({ title:"", slides:[] }); const detail=ref<PptTaskResponse>({taskId:"",status:"pending",title:"",pptUrl:"",pdfUrl:"",errorMessage:"",slides:[]});
const detailLoading=ref(false); const detailError=ref(""); const previewIndex=ref(0); const activeSlide=ref<PptSlide>(emptySlide());
const bulletText=ref(""); const selectedColor=ref("#6140f7"); const layoutTab=ref("全部"); const selectedLayout=ref("imageText");
const exportFormat=ref<"pptx"|"pdf">("pptx"); const exportBusy=ref(false); const exportReady=ref(false);
const errorTitle=ref("PPT生成失败"); const errorReason=ref("服务暂时无法完成本次操作"); const errorSuggestion=ref("请返回修改内容后重试，或稍后再试。");
const inspirationTemplateId=ref("");
const taskId = computed(() => String(query().taskId || detail.value.taskId || ""));
const slides = computed(() => detail.value.slides || []); const totalSlides=computed(()=>taskState.task.value?.slideCount || slides.value.length || form.value.pageCount);
const taskProgress=computed(()=>Math.max(0,Math.min(100,taskState.progress.value || (taskState.task.value?.status === "processing" ? 30 : 0))));
const pageTitle=computed(()=>({index:"PPT助手",create:"创建PPT",outline:"确认大纲",progress:"PPT生成中",detail:"PPT详情",preview:"", "edit-text":"编辑文字","edit-visual":"编辑视觉",layout:"选择布局",export:"导出与分享",desktop:"在电脑端继续编辑",error:"生成失败"}[mode.value]));
const showFixedBar=computed(()=>["create","outline","edit-text","edit-visual","layout"].includes(mode.value));
const canSubmitCreate=computed(()=>!busy.value&&Boolean(form.value.topic.trim())&&estimate.value?.sufficient!==false);
const pageCounts=[5,8,10,12,16,20,24]; const languages=[{label:"中文",value:"zh"},{label:"英文",value:"en"}] as const;
const scenarios=[{label:"企业汇报",value:"business"},{label:"教育培训",value:"education"},{label:"产品发布",value:"product"},{label:"项目路演",value:"pitch"}];
const styles=[{label:"简约商务",value:"business"},{label:"科技蓝",value:"techBlue"},{label:"教育培训",value:"education"},{label:"营销方案",value:"marketing"},{label:"项目路演",value:"pitch"},{label:"医疗科普",value:"medical"}];
const templates=[{id:"business",name:"企业汇报",scenario:"business",icon:"汇",tone:"purple"},{id:"education",name:"教育培训",scenario:"education",icon:"教",tone:"blue"},{id:"product",name:"产品发布",scenario:"product",icon:"品",tone:"orange"},{id:"tech-blue",name:"科技蓝商务模板",scenario:"business",icon:"科",tone:"blue"}];
const pageCountIndex=computed(()=>Math.max(0,pageCounts.indexOf(form.value.pageCount))); const languageIndex=computed(()=>Math.max(0,languages.findIndex(i=>i.value===form.value.language))); const scenarioIndex=computed(()=>Math.max(0,scenarios.findIndex(i=>i.value===form.value.scenario))); const styleIndex=computed(()=>Math.max(0,styles.findIndex(i=>i.value===form.value.style))); const templateIndex=computed(()=>Math.max(0,templates.findIndex(i=>i.id===form.value.templateId)));
const languageLabel=computed(()=>languages[languageIndex.value]?.label || "中文"); const scenarioLabel=computed(()=>scenarios[scenarioIndex.value]?.label || "企业汇报"); const styleLabel=computed(()=>styles[styleIndex.value]?.label || "简约商务"); const templateLabel=computed(()=>templates[templateIndex.value]?.name || "未选择模板");
const progressSteps=computed(()=>{const p=taskProgress.value; return [{id:"analysis",label:"分析主题与资料",edge:10},{id:"outline",label:"生成PPT大纲",edge:25},{id:"content",label:"生成页面内容",edge:55},{id:"visual",label:"生成页面设计",edge:80},{id:"layout",label:"优化与排版",edge:95},{id:"done",label:"生成完成",edge:100}].map((s,i,a)=>({...s,state:p>=s.edge?"done":p>=(a[i-1]?.edge||0)?"active":"wait"}));});
const aiTextActions=["内容更简洁","内容更专业","减少文字","增加数据感","改成三个要点","改成流程结构","改成对比结构"];
const themeColors=["#e3e5f0","#051440","#1457e0","#ffffff","#6140f7","#22c982"];
const layoutTabs=["全部","图文","数据","文字","其他"]; const layouts=[{id:"cover",name:"标题页",cat:"文字",icon:"AI"},{id:"imageText",name:"图文左右",cat:"图文",icon:"▧"},{id:"imageTop",name:"图文上下",cat:"图文",icon:"▤"},{id:"columns",name:"三栏内容",cat:"文字",icon:"▥"},{id:"data",name:"数据卡片",cat:"数据",icon:"▦"},{id:"timeline",name:"时间轴",cat:"其他",icon:"→"},{id:"comparison",name:"对比关系",cat:"数据",icon:"⇆"},{id:"content",name:"纯文字",cat:"文字",icon:"文"},{id:"heroImage",name:"大图展示",cat:"图文",icon:"▣"}];
const filteredLayouts=computed(()=>layoutTab.value==="全部"?layouts:layouts.filter(item=>item.cat===layoutTab.value)); const exportFormats=["pptx","pdf"] as const;

function query(){const pages=typeof getCurrentPages==="function"?getCurrentPages():[]; return (pages[pages.length-1] as unknown as {options?:Record<string,string>})?.options || {};}
function emptySlide():PptSlide{return {id:"",page:1,title:"",content:"",bulletPoints:[],layout:"content",speakerNotes:""};}
function route(path:string,params:Record<string,string|number|undefined>={}){const qs=Object.entries(params).filter(([,v])=>v!==undefined&&v!=="").map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join("&"); uni.navigateTo({url:`/packagePpt/pages/${path}${qs?`?${qs}`:""}`});}
function replaceRoute(path:string,params:Record<string,string|number|undefined>={}){const qs=Object.entries(params).filter(([,v])=>v!==undefined&&v!=="").map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join("&");uni.redirectTo({url:`/packagePpt/pages/${path}${qs?`?${qs}`:""}`});}
function goBack(){uni.navigateBack({fail:()=>uni.switchTab({url:"/pages/user/UserCreationPage"})});} function showToast(title:string){uni.showToast({title,icon:"none"});}
function openCreate(seed:Record<string,string>={}){Object.assign(form.value,seed); route("create");} function openDetail(id:string){route("detail",{taskId:id});} function openPreview(index:number){route("preview",{taskId:taskId.value,index});} function openTextEditor(index:number){route("edit-text",{taskId:taskId.value,index});} function openVisualEditor(index:number){route("edit-visual",{taskId:taskId.value,index});} function openExport(){route("export",{taskId:taskId.value});}
function openAssets(){uni.switchTab({url:"/pages/user/UserAssetsPage"});} function openWallet(){uni.navigateTo({url:"/pages/user/UserWalletPage"});}
function formatDate(value?:string){if(!value)return "刚刚"; const d=new Date(value); return Number.isNaN(d.getTime())?value:`${d.getMonth()+1}/${d.getDate()} ${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;}
function statusLabel(s:string){return ({pending:"排队中",processing:"生成中",success:"已完成",failed:"失败"} as Record<string,string>)[s]||s;}
async function loadHistory(){historyLoading.value=true;historyError.value="";try{recent.value=(await listPptHistory()).slice(0,3);}catch(e){historyError.value=message(e);}finally{historyLoading.value=false;}}
function requestPayload(){return {prompt:[form.value.topic,form.value.description].filter(Boolean).join("。"),slideCount:form.value.pageCount,language:form.value.language,theme:(form.value.style as "business"),enableWebSearch:false,tone:"professional",scenario:form.value.scenario,imageSource:form.value.generateVisuals?"ai" as const:"none" as const,imageModel:"default-image",outline:outline.value.slides.length?outline.value:undefined};}
async function refreshEstimate(){if(!form.value.topic.trim()){estimate.value=null;return;}try{estimate.value=await estimatePptCost(requestPayload());}catch{estimate.value=null;}}
async function submitCreate(){if(!form.value.topic.trim()||busy.value)return;busy.value=true;createError.value="";try{await refreshEstimate();outline.value=await generatePptOutline(requestPayload());uni.setStorageSync("xianzhi:ppt:v2:outline",outline.value);route("outline",{templateId:inspirationTemplateId.value});}catch(e){createError.value=message(e);}finally{busy.value=false;}}
async function regenerateOutline(){if(busy.value)return;busy.value=true;try{outline.value=await generatePptOutline(requestPayload());uni.setStorageSync("xianzhi:ppt:v2:outline",outline.value);}catch(e){createError.value=message(e);}finally{busy.value=false;}}
function moveOutline(index:number,delta:number){const target=index+delta;if(target<0||target>=outline.value.slides.length)return;const list=[...outline.value.slides];[list[index],list[target]]=[list[target],list[index]];outline.value.slides=list.map((s,i)=>({...s,page:i+1}));persistOutline();}
function removeOutline(index:number){outline.value.slides.splice(index,1);outline.value.slides=outline.value.slides.map((s,i)=>({...s,page:i+1}));persistOutline();}
function addOutline(){outline.value.slides.push({page:outline.value.slides.length+1,title:"新增章节",summary:"补充本页要表达的核心信息",bulletPoints:["核心观点"],layout:"content",slideType:"text_image"});persistOutline();}
function persistOutline(){uni.setStorageSync("xianzhi:ppt:v2:outline",outline.value);}
async function confirmGeneration(){if(busy.value)return;busy.value=true;createError.value="";try{outline.value=await savePptOutline(outline.value);const result=await createPptGenerationTask(requestPayload());clearDraft();route("progress",{taskId:result.taskId,templateId:inspirationTemplateId.value});}catch(e){createError.value=message(e);}finally{busy.value=false;}}
async function loadDetail(){if(!taskId.value)return;detailLoading.value=true;detailError.value="";try{detail.value=await getPptGenerationTask(taskId.value);}catch(e){detailError.value=message(e);}finally{detailLoading.value=false;}}
async function loadSlide(){await loadDetail();const index=Math.max(0,Number(query().index||0));previewIndex.value=index;activeSlide.value={...(detail.value.slides?.[index]||emptySlide())};bulletText.value=(activeSlide.value.bulletPoints||[]).join("\n");selectedLayout.value=activeSlide.value.layout||"content";}
async function saveText(){if(!taskId.value||!activeSlide.value.id||busy.value)return;busy.value=true;try{activeSlide.value.bulletPoints=bulletText.value.split(/\n+/).map(v=>v.trim()).filter(Boolean);activeSlide.value=await updatePptSlide(taskId.value,activeSlide.value.id,activeSlide.value);showToast("当前页已保存");goBack();}catch(e){createError.value=message(e);}finally{busy.value=false;}}
function applyTextAction(action:string){if(action.includes("三个要点")){bulletText.value=bulletText.value.split(/\n+/).filter(Boolean).slice(0,3).join("\n");return;}if(action.includes("减少")||action.includes("简洁"))bulletText.value=bulletText.value.split(/\n+/).map(v=>v.slice(0,36)).join("\n");else showToast(`${action}需要接入单页AI改写接口`);}
async function regenerateVisual(){if(!activeSlide.value.id||busy.value)return;busy.value=true;try{const result=await regeneratePptSlideVisual(taskId.value,activeSlide.value.id,{visualType:"illustration",style:"clean",composition:"right",customInstruction:"适合演示文稿的无文字配图",keepCurrentContent:true});activeSlide.value=result.slide;showToast("配图已更新");}catch(e){createError.value=message(e);}finally{busy.value=false;}}
async function applyLayout(){if(!taskId.value||!activeSlide.value.id||busy.value)return;busy.value=true;try{activeSlide.value=await updatePptSlide(taskId.value,activeSlide.value.id,{...activeSlide.value,layout:selectedLayout.value});showToast("布局已应用");goBack();}catch(e){createError.value=message(e);}finally{busy.value=false;}}
async function chooseVisual(){if(!taskId.value||!activeSlide.value.id||busy.value)return;uni.chooseImage({count:1,success:async r=>{const path=String(r.tempFilePaths[0]||"");if(!path)return;busy.value=true;createError.value="";try{const url=await uploadReferenceImage(path);activeSlide.value=await updatePptSlideImage(taskId.value,activeSlide.value.id,url);showToast("配图已更新");}catch(e){createError.value=message(e);}finally{busy.value=false;}}});}
async function cancelTask(){if(!taskId.value)return;uni.showModal({title:"取消生成",content:"取消后已生成内容仍会保留，确定继续吗？",success:async r=>{if(!r.confirm)return;try{await deletePptTask(taskId.value);taskState.stop();goBack();}catch(e){showToast(message(e));}}});}
function continueInBackground(){uni.switchTab({url:"/pages/user/UserAssetsPage"});}
function showDetailMore(){uni.showActionSheet({itemList:["调整布局","电脑端继续编辑","删除PPT"],success:r=>{if(r.tapIndex===0)route("layout",{taskId:taskId.value,index:0});if(r.tapIndex===1)route("desktop",{taskId:taskId.value});if(r.tapIndex===2)cancelTask();}});}
async function startExport(){if(!taskId.value||exportBusy.value)return;exportBusy.value=true;createError.value="";try{const path=await downloadPptExport(taskId.value,exportFormat.value);exportReady.value=true;uni.openDocument({filePath:path,showMenu:true,fail:()=>{createError.value="文件已下载，但当前设备无法直接打开，请使用兼容的 Office 应用。";}});}catch(e){createError.value=message(e);}finally{exportBusy.value=false;}}
function copyUnavailable(){showToast("临时分享链接接口尚未接入，未复制无效地址");} function retryFromError(){goBack();} function message(e:unknown){return e instanceof Error?e.message:String(e||"操作失败");}
function setPageCount(e:any){form.value.pageCount=pageCounts[Number(e.detail.value)]||16;void refreshEstimate();} function setLanguage(e:any){form.value.language=languages[Number(e.detail.value)]?.value||"zh";} function setScenario(e:any){form.value.scenario=scenarios[Number(e.detail.value)]?.value||"business";} function setStyle(e:any){form.value.style=styles[Number(e.detail.value)]?.value||"business";} function setTemplate(e:any){form.value.templateId=templates[Number(e.detail.value)]?.id||"business";}

watch(()=>form.value.topic,()=>{createError.value="";});
watch(()=>pollingTask.value?.status,status=>{if(mode.value!=="progress"||!taskId.value)return;if(status==="success"){taskState.stop();if(inspirationTemplateId.value){void inspirationAPI.event(inspirationTemplateId.value,"generate_success",taskId.value);inspirationTemplateId.value="";}replaceRoute("detail",{taskId:taskId.value});}else if(status==="failed"){const reason=pollingTask.value?.errorMessage||"PPT生成失败，请稍后重试";taskState.stop();replaceRoute("error",{title:"PPT生成失败",reason});}});
onMounted(async()=>{const q=query();inspirationTemplateId.value=String(q.templateId||"");if(mode.value==="index")await loadHistory();if(mode.value==="create"){const draft=readInspirationDraft(inspirationTemplateId.value);if(draft?.contentType==="ppt"){const params=draft.parameters||{};form.value.topic=draft.prompt;form.value.description=draft.negativePrompt;form.value.pageCount=Number(params.pageCount||form.value.pageCount);form.value.language=String(params.language||form.value.language) as typeof form.value.language;form.value.scenario=String(params.scenario||form.value.scenario);form.value.style=String(params.style||form.value.style);form.value.generateVisuals=params.withImages!==false;}else{if(q.topic)form.value.topic=q.topic;if(q.templateId)form.value.templateId=q.templateId;if(q.scenario)form.value.scenario=q.scenario;}await refreshEstimate();}if(mode.value==="outline"){outline.value=uni.getStorageSync("xianzhi:ppt:v2:outline")||outline.value;await refreshEstimate();}if(["detail","preview","edit-text","edit-visual","layout"].includes(mode.value))await loadSlide();if(mode.value==="progress"&&taskId.value)taskState.start(taskId.value);if(mode.value==="error"){errorTitle.value=query().title||errorTitle.value;errorReason.value=query().reason||errorReason.value;}});
onShow(()=>{taskState.setVisible(true);});onHide(()=>taskState.setVisible(false));onUnload(()=>taskState.stop());
</script>

